dict(toc='People\'s participation and local self-government reforms', id=21, title='PEOPLE\'S PARTICIPATION &amp; LOCAL SELF-GOVERNMENT', part=2, icon='people', prio='L',
 pyq='none quoted in the handout · Handout GEG pp. 7-9',
 simple='Participation goes beyond voting: people shape and watch the work. It needs social capital, equality and strong local bodies, and it is blocked by caste, class, gender and powerlessness.',
 nodes=[
 bx('pk', '<b>Participation goes beyond voting.</b> A person feels liberated when his issues truly get addressed by the authorities responsible: he then truly participates (e.g. <b>Mohalla committees</b>), and people\'s participation becomes the mainstream paradigm of governance, "almost a re-birth of society". The right to participate should be a <b>fundamental right</b>, especially in aspects of governance affecting citizens\' daily lives.'),
 t('<b>Benefits</b>', 'more information; check fit with ground reality; less policy failure', 'social acceptance and ownership; sustainable projects', '<b>two-way learning</b>: government learns from people, people learn technical aspects from government; with time government\'s responsibility for the project falls and people\'s involvement rises', 'capacity building; vigilance, less pilferage and corruption', 'community feeling, social capital; volunteer resources', w=24),
 two([t('<b>Pre-requisites</b>', 'a basic, rudimentary level of <b>social capital</b> before participation can even start', 'equality of wealth and power widens the social base of participation', 'institutional environment: local self-government', 'procedural reforms to involve people', w=18)],
     [t('<b>Barriers</b>', '<b>caste:</b> upper castes dominate', '<b>class:</b> landed control', '<b>gender:</b> male-dominated Gram Sabhas', '<b>powerlessness:</b> people must be prepared to participate, not just asked', '<b>low capacity:</b> basic education, awareness of rights and legal framework', '<b>political:</b> lack of decentralisation', w=18)]),
 OWN('CCG LPC', 'Barriers: <b>C</b>aste · <b>C</b>lass · <b>G</b>ender · <b>L</b>ack of motivation · <b>P</b>olitical constraints · <b>C</b>apacity gap.'),
 sec('URBAN LOCAL BODIES', 'b'),
 bx('bl', '<b>74th Amendment ULBs:</b> critical to democratic decentralisation, but constrained by inadequate devolution of <b>3Fs: functions, finances, functionaries</b>. Municipal own revenue <b>below 1% of GDP</b> (RBI 2024) vs South Africa ~6%. <b>State dependence:</b> States retain control over municipal finances and functionaries, diluting autonomy. <b>Capacity deficit:</b> administrative, technological and human-resource.'),
 t('<b>Reforms</b>', '<b>Empower State Finance Commissions:</b> constitutional mandate for timely reports, transparent devolution formula, monitoring (2nd ARC, 13th FC)', '<b>Functional autonomy:</b> Model Municipal Law for urban planning, water supply, sanitation, public health', 'e-municipality; GIS revenue mapping (BBMP Bengaluru)', '<b>fiscal powers:</b> municipal bonds, user fees, property-tax reform (geo-spatial mapping in Pune, Hyderabad raised tax base by 40%)', 'institutionalise <b>Ward Committees and Area Sabhas</b> as mandated under 74th Amendment for participatory planning', 'integrated urban data platforms', w=26),
 tb(['Best practice', 'Detail'], ['Ahmedabad Municipal Corporation', 'pioneered India\'s first municipal bonds, <b>1998</b>: model for infrastructure financing'], ['Pune Smart Governance', 'GIS-enabled property tax: <b>35%</b> increase in revenue'], ['Delhi Mohalla Sabhas', 'pilot ward participatory budgeting; needs scale and legal backing']),
 sec('GRAM SABHAS', 'g'),
 bx('pk', '<b>73rd Amendment:</b> Gram Sabhas are the foundation of grassroots democracy but under-used: poor attendance (<b>often below 15%</b> in many states, MoPR survey 2023), <b>bureaucratic dominance</b>, resolutions seen as <b>recommendatory, not binding</b> (no statutory enforcement); PRIs lack training in participatory planning, budgeting and social auditing.'),
 t('<b>Way forward</b>', '<b>statutory backing</b> to Gram Sabha resolutions, esp. in planning and social audits of schemes like MGNREGA', '<b>e-GramSwaraj</b> to track attendance, decisions and follow-up', 'reserved discussion slots for women, SC/ST, SHG members in every meeting (Kerala People\'s Plan Campaign)', 'mandate Gram Sabha-led social audits: downward accountability', '<b>Panchayat Resource Centres</b> to train PRI functionaries on participatory tools', w=24),
 tb(['Practice / report', 'Detail'], ['Jharkhand Social Audit Unit', 'institutionalised Gram Sabha-led MGNREGA audits; exposed over <b>Rs 18 crore</b> irregularities'], ['Kerala People\'s Plan Campaign', 'Gram Sabhas formulated local development plans (rural development index recognition)'], ['Chhattisgarh Jan-Choupal', 'Gram Sabha-level grievance redressal and planning forums; better local responsiveness'], ['13th Finance Commission', 'performance-linked grants for PRIs, linking funds to Gram Sabha functionality'], ['Bhuria Committee 1995', 'recommended Gram Sabha\'s pivotal role in tribal self-governance'], ['MoPR 2024', 'flagged irregular Gram Sabha functioning in <b>60%</b> of surveyed villages']),
 sec('MINIMUM GOVERNMENT, MAXIMUM GOVERNANCE', 'r'),
 bx('ye', '<b>Not essentially less bureaucracy but a better bureaucracy.</b> Components: do away with crippling regulations · reduce bureaucrats\' discretionary powers · goals over rules · effective facilitation of business and civil society organisations · effective accountability mechanism. <b>Steps:</b> self-certification in place of gazetted-officer certification · drive to identify obsolete rules · labour-law amendments to reduce inspector raj, benchmarking best practices for industrial clearances · single window (ends inter-departmental wrangling) · introduction of e-governance.'),
 bx('ca', '<span class="tag">Link · Saarthi IAS CA (verify)</span>Low Gram Sabha participation (NIRDPR study) is covered in Chapter 16: barriers, elite capture and ARC-II suggestions.'),
 ],
 recall=[('Beyond voting example', 'Mohalla committees'), ('3Fs of ULBs', 'functions, finances, functionaries'), ('Municipal revenue', 'below 1% of GDP (RBI 2024)'), ('First municipal bond', 'Ahmedabad, 1998'), ('Gram Sabha attendance', 'below 15% in many states (MoPR 2023)')]),

dict(toc='E-governance: stages, models, benefits, issues', id=22, title='E-GOVERNANCE', part=2, icon='eye', prio='H',
 pyq='Mains 2025 · 2024 · 2023 · 2021 · 2020* · 2019 · 2018 · 2013 · Handout GEG pp. 9-14',
 simple='E-government digitises the government\'s own work. E-governance uses ICT to deliver services through state, market and civil society together. Learn stages, four models, ten benefits, and the issues (divide, trust, no re-engineering).',
 nodes=[
 tb(['E-Government', 'E-Governance'], ['a more efficient form of government made possible by increasing, extensive use of ICT to manage <b>its own internal processes</b>', 'based on the <b>triangulation model</b> (state-market-civil society): comprehensive delivery of public goods and services exploiting the <b>synergies</b> between the three, with ICT as the platform']),
 fl(['One-way information (website)', 'Two-way communication (queries)', 'Services and payments (bills, returns, GST)', 'Integration (same server, LAN/WAN)', 'Participation (e.g. mygov.in)'], 'FIVE STAGES (in order)', 3),
 t('<b>Stages in detail</b>', '<b>1 Simple information dissemination:</b> website reaches people about programmes; <b>one-way</b> data transfer; most basic form', '<b>2 Two-way communication:</b> <b>demand-driven</b> data transfer; extra pages of information; a user unable to find information can <b>put a query</b> on the site', '<b>3 Services and financial transactions:</b> things people did physically (services, transactions with governmental and non-governmental entities) become digital: bill payment, filing returns, GST or income tax payment', '<b>4 Integration:</b> same server or database connects every employee vertically and horizontally in a department; extended to other departments, ministries and national-state-local governments by <b>LAN and WAN</b>', '<b>5 Popular participation:</b> sites designed for flow from people to government too: opinions on proposed legislation or policy (mygov.in)', w=38),
 sec('FOUR MODELS ' + P('2024'), 'b'),
 tb(['Model', 'Idea'], ['<b>Broadcasting</b>', 'without internet, information was limited; e-governance gives an <b>exponential rise</b> in flow of information; earlier less access meant less informed decisions, now more informed and empowered citizens'], ['<b>Critical Information Flow</b>', 'critical information needed for a person\'s growth; farmer needs weather forecast, pesticide use, prevailing price of his produce; earlier cost money, time and energy, now one click, no travel to mandi'], ['<b>E-Mobilisation</b>', 'enforces democratic rights by mobilising people <b>virtually</b>: physical space for assembling is limited; protest in the virtual world and pressure government; democracy-enhancing, citizen-to-citizen engagement'], ['<b>Interactive Service</b>', 'improves pace and quality of services: earlier visit offices and queue for utility bills, now at the push of a button; private sector e-commerce (Amazon, Flipkart); improves B2C, B2B, G2B interactions']),
 OWN('BCEI', 'Four models in handout order: <b>B</b>roadcasting · <b>C</b>ritical information flow · <b>E</b>-mobilisation · <b>I</b>nteractive service.'),
 sec('BENEFITS (ten)', 'g'),
 t('<b>Benefits</b>', '<b>1 Administration (overcomes historic disabilities):</b> e-files cut delay (seconds/minutes between departments); team work (copy sent to all, immediate comments); <b>central storage with multiple backups</b> (Adarsh Society scam: documents destroyed); less paperwork, carbon footprint (fewer trees cut), manpower and space; so better intended finance', '<b>2 Sound data management for planning and decisions:</b> manual processing limited, computer analytics better; Vikas Darpan (Rajasthan GIS-based decision support); CPGRAMS: aggregated complaints show which departments or procedures need amendment', '<b>3 Service delivery:</b> e-FIR (Delhi); rural: land records, agriculture information (seeds, pests, weather, crop disease, prices); utility bills; policing (lost and found, e-FIR); licences, passport, ration card; Where is My Train, RailYatri; e-filing of returns; single-window <b>ME-SEVA</b> (Andhra), <b>FRIENDS</b> (Kerala: Fast, Reliable, Instant, Effective Network for Disbursement of Services)', '<b>4 Lower transaction cost and end-to-end time:</b> simultaneous processing, no department-by-department trail', '<b>5 Process re-engineering:</b> NIC support; digitisation delayed by complex procedures; rules must be simplified before digitising; status checkable even on off days', '<b>6 Anytime-anywhere (24x7):</b> status and new applications', '<b>7 Transparency:</b> corruption-prone areas lose the physical interface; transparency, accountability up, corruption down', '<b>8 Democracy:</b> democratic deficit in physical space organised digitally; communities, propaganda or protest on Twitter/Facebook; citizen-to-citizen mobilisation, G2C interface, EVM', '<b>9 Judicial administration:</b> video-conferencing, judicial data grid', '<b>10 Government revenue:</b> digital payments reflect white money in banks, so taxes cannot be avoided; black money falls', w=40),
 sec('ISSUES ' + P('2023') + P('2021') + P('2019'), 'r'),
 hub('E-GOV ISSUES', ['Digital divide', 'Digital trust gap', 'No re-engineering', 'No consultation', 'Transparency only incidental', 'Not a panacea'], 'WHAT HOLDS E-GOVERNANCE BACK'),
 bx('pk', '<b>Digital divide:</b> <b>75% of net users are in urban India</b>; digital illiteracy in rural India (an illiterate person cannot use online services even with a smartphone); mirrors the urban-rural divide (COVID: urban middle-class students on Zoom, rural students excluded; imbalance in education); rural people miss income opportunities, telemedicine; elderly more vulnerable; inadequate <b>vernacular</b> content; <b>last-mile connectivity</b> still a problem.'),
 bx('ye', '<b>Digital trust:</b> entering personal information for transactions or fee payment makes people insecure about <b>misuse of data</b>.'),
 mn('6 C\'s', 'Teacher\'s <b>6 C\'s of work plan:</b> <b>C</b>ontent development (revise regularly, relevant to the zone) · <b>C</b>ompetence building (e.g. bank staff blame "server fault" and wait for an expert: give basic ICT training) · <b>C</b>onnectivity, esp. rural (else only the integrated part benefits, majority left on margins) · <b>C</b>itizen\'s interface (needs phone and internet; internet costly for rural people; awareness; accessible and affordable) · <b>C</b>yber laws (data protection and security; <b>technology-agnostic</b>; balance privacy so that productive use of technology is not compromised) · <b>C</b>apital (sites need revenue streams; reasonable charges, self-sustaining).'),
 two([bx('ye', '<b>Inadequate re-engineering:</b> e-governance lets government restructure and simplify procedure; if not done, procedure never gets digitised. Delay is not because of support agencies but sometimes govt lacks interest in simplifying, as the <b>corruption point barricades</b> digitisation.')], [bx('ye', '<b>Narrow vision, no consultation:</b> services shifted from physical to digital without asking stakeholders whether it fits their needs; if consulted first and physical-world problems resolved, e-governance matches needs. <b>Check on corruption and transparency only incidental:</b> dip is automatic from removing human interface; design intervention for the twin goals of accountability and transparency.')]),
 tb(['E-governance helps', 'But it cannot'], ['smart classes, presentations, online assignments, parents\' access to progress', 'build adequate schools with adequate teachers'], ['manage traffic: GPS load analysis, signals, CCTV challans', 'care about congestion, deficit of flyovers/underpasses, road quality'], ['judicial data, case status, next hearing, lawyer allotment, bench', 'give speedy justice delivery'], ['easy tax payment', 'ensure government accountability for development works and use of taxes']),
 bx('gr', '<b>Big data ("Data is the new oil"):</b> with increasing data, problems arise: data security, privacy, unethical usage.'),
 tb(['Year', 'PYQ (handout, with marks)'], ['2025 (10)', 'E-governance projects have a built-in bias towards technology and back-end integration than user-centric designs. Examine.'], ['2024 (15)', 'E-governance is not just routine digital technology in service delivery but multifarious interactions for transparency and accountability: evaluate the role of the \'Interactive Service Model\'.'], ['2023 (10)', 'E-governance has ushered in effectiveness, transparency, accountability. What inadequacies hamper enhancement of these features?'], ['2021 (15)', 'Has digital illiteracy, particularly in rural areas, coupled with lack of ICT accessibility hindered socio-economic development? Examine with justification.'], ['2020 (10)', 'Fourth Industrial Revolution (Digital Revolution) has initiated e-Governance as an integral part of government. Discuss.'], ['2019 (10)', 'ICT-based projects usually suffer in vital factors. Identify these and suggest measures for effective implementation.'], ['2018 (10)', 'E-Governance is not only about new technology but the critical importance of the \'use value\' of information. Explain.'], ['2013 (10)', 'Electronic cash transfer for welfare schemes: an ambitious project to minimise corruption, eliminate wastage and facilitate reforms. Comment.']),
 ],
 recall=[('E-government vs e-governance', 'internal efficiency vs state-market-civil society delivery'), ('Five stages', 'info, two-way, transactions, integration, participation'), ('Four models', 'broadcasting, critical info flow, e-mobilisation, interactive service'), ('Digital divide statistic', '75% of net users urban'), ('Six C\'s', 'content, competence, connectivity, citizen interface, cyber laws, capital')]),

dict(toc='Data protection, privacy and cybersecurity', id=23, title='DATA PROTECTION, PRIVACY &amp; CYBERSECURITY', part=2, icon='book', prio='L',
 pyq='none quoted in the handout · Handout GEG pp. 15-20',
 simple='Data is the new oil, and also a liability. India moved from IT Rules 2011 → Puttaswamy 2017 → Srikrishna Committee → PDP Bill 2019 (a Bill) → Digital Personal Data Protection Act 2023 (an Act). Keep Bill and Act apart.',
 nodes=[
 bx('pk', '<b>India:</b> about <b>800 million</b> internet users, <b>400 million</b> smartphone users, <b>150 exabytes</b> of data a year (handout). Strategic asset and liability. <b>132 of 194</b> countries have data-protection frameworks. Rise of big data, tech giants and data aggregation raises privacy-breach and profiling concerns: even India\'s poorest are integrated through Aadhaar-linked services. The Parliamentary Committee on the PDP Bill noted data volumes expanding exponentially: opportunities and governance challenges.'),
 bx('gr', '<b>Need for protective data usage:</b> harness data for growth, better public services and <b>Atmanirbhar Bharat</b>; cross-sectoral data convergence (Aadhaar, GSTN, UPI, BHUVAN) can improve policy through <b>predictive analytics</b>; but privacy and security are imperative to keep public trust while maximising economic benefit.'),
 sec('ISSUES IN THE DATA ECOSYSTEM', 'r'),
 t('<b>Issues</b>', '<b>data security and privacy:</b> prevent misuse for commercial gain; over-regulation stifles innovation, lax control erodes public confidence; <b>privacy by design</b> while enabling economic use', '<b>cross-border compatibility:</b> align with global norms so firms operating internationally face no conflict; debate: uniform across private and public sectors or sector-specific; extent of government exemptions', '<b>medico-legal:</b> leaks cause not just financial loss but emotional and psychological harm: stress, depression, PTSD (Identity Theft Resource Center study); law must integrate medico-legal safeguards', '<b>fake accounts and bots:</b> mimic humans, spread propaganda and misinformation (NYT: 48 million Twitter accounts fake: malicious campaigns, scams)', '<b>social media abuse by anti-social elements:</b> extremist and terror outfits (ISIS recruitment); tension between privacy and national security: needs government-platform cooperation', w=40),
 sec('DATA LOCALISATION', 'b'),
 bx('bl', '<b>Data localisation</b> = restrictions on cross-border data flow: local storage with regulated external access. <b>Hard:</b> absolute restriction on data leaving national borders. <b>Soft:</b> stored locally with conditional cross-border sharing. Key challenge: defining clear <b>purpose-specific conditions</b> for permissible transfers.'),
 t('<b>Benefits (detail)</b>', '<b>national security:</b> hostile nations cannot access information on our population to manipulate it', '<b>law enforcement:</b> easier access for investigation; abroad it is difficult and impedes investigation', '<b>privacy:</b> government can impose its own privacy rules; otherwise data flows where regulation may be lenient', '<b>grievance redressal:</b> breach can be pursued in an Indian court; not feasible if breach occurs abroad', '<b>bargaining power:</b> local data is an asset in deals with countries and multilateral institutions (market access, bilateral, technical and economic cooperation)', w=40),
 OWN('SLIPB', 'Benefits: <b>S</b>ecurity (national) · <b>L</b>aw enforcement access · <b>I</b>ndia\'s own privacy rules apply · <b>P</b>rivacy grievance in Indian courts · <b>B</b>argaining power.'),
 sec('LEGAL PATH (in order)', 'g'),
 tl(('2000 / 2011', 'IT Rules 2011 under IT Act 2000 defined Reasonable Security Practices and Sensitive Personal Data Rules; inadequate against rising privacy concerns, so a comprehensive PDP Bill was needed'), ('2017', 'Puttaswamy: Right to Privacy a Fundamental Right, so government must build a robust legal framework; Justice B.N. Srikrishna Committee formed to draft the law'), ('2018', 'Srikrishna report laid the foundation for India\'s first PDP Bill'), ('2019', '<b>PDP Bill 2019</b> (a Bill); several progressive recommendations were omitted or diluted in the final draft, leaving gaps'), ('2023', '<b>DPDP Act, 2023</b> (an Act)')),
 bx('ye', '<b>Bill vs Act:</b> PDP Bill 2019 was only a Bill (handout: Departmental Standing Committee; a JPC examined it and it was withdrawn in 2022: general knowledge, verify). Law in force: <b>DPDP Act 2023</b>.'),
 t('<b>GDPR (EU, 2018): "EU avatar" of the Indian PDP Bill</b>', '<b>informed consent:</b> lengthy complex online consent causes <b>consent fatigue</b>; terms should be simplified, shortened, understandable', '<b>breach notification:</b> the moment data is breached, the individual must be informed immediately', '<b>automated decision-making:</b> AI recommendation algorithms build profiles; right to <b>opt out</b> to prevent profiling', '<b>citizen awareness:</b> mass citizen-engagement programme', w=36),
 t('<b>Principles of data protection (7)</b>', '<b>technology agnosticism:</b> adaptive, future-proof; avoids frequent overhauls', '<b>holistic application:</b> private entities and government; <b>narrow, well-defined exemptions</b> (national security, public order, investigation) to prevent misuse of discretion', '<b>informed consent:</b> genuine choice, not procedural formality from consent fatigue', '<b>data minimisation:</b> collect only what is strictly necessary; purpose-limited use', '<b>controlled accountability:</b> fiduciaries proactively use advanced security; accountable for breach under a defined framework', '<b>structured enforcement:</b> multi-tier: company, independent regulator, tribunals, judiciary (HC, SC)', '<b>deterrent penalties</b> as envisaged in the PDP Bill, to ensure compliance and trust', w=40),
 OWN('SHARP-DD', 'Principles: <b>S</b>tructured enforcement · <b>H</b>olistic cover (private + govt) · <b>A</b>gnostic technology · <b>R</b>esponsible fiduciary · <b>P</b>urpose-limited minimisation · <b>D</b>eterrent penalties · <b>D</b>ata consent (informed).'),
 sec('PDP BILL 2019 (provisions of the Bill)', 'b'),
 t('<b>Bill provisions</b>', '<b>preamble:</b> right to privacy is a fundamental right; protect personal data as a facet of privacy; collective culture for a free and fair digital economy', '<b>applies to:</b> government, companies incorporated in India, foreign companies dealing with personal data of individuals in India', '<b>personal data:</b> traits or attributes of identity that identify an individual; <b>sensitive:</b> financial, biometric, caste, religious or political belief, or other category the government specifies with the Authority and sectoral regulator', '<b>data fiduciary:</b> entity or individual deciding means and purpose of processing; only for specific, clear, lawful purposes, within collection and storage limits; security safeguards (encryption, preventing misuse), grievance redress, age verification and parental consent for sensitive data of children', '<b>rights of data principal:</b> confirmation of processing, correction of inaccurate/incomplete/out-of-date data, portability to another fiduciary, restrict continuing disclosure when no longer necessary or consent withdrawn', '<b>consent is the basis;</b> no consent needed for: benefits by the State, legal proceedings, medical emergency', '<b>social media intermediaries:</b> enable user interaction; above a notified threshold and able to affect electoral democracy or public order: voluntary user verification', '<b>Authority:</b> protects individuals\' interests, prevents misuse, ensures compliance; chair + 6 members with at least 10 years in data protection and IT; appeal to Appellate Tribunal, then Supreme Court', '<b>transfer abroad:</b> sensitive data only with explicit consent plus conditions, and must still be stored in India; <b>critical personal data</b> (notified) processed only in India', '<b>exemptions:</b> Centre can exempt its agencies (security of state, public order, sovereignty and integrity, friendly relations, preventing incitement to cognizable offences); also prevention/investigation/prosecution of offences, personal or domestic, journalistic purposes (still specific, clear, lawful, with safeguards)', '<b>penalty:</b> violation Rs 15 crore or 4% of annual turnover, whichever higher; failure of data audit Rs 5 crore or 2%; re-identification without consent: up to 3 years, fine or both', w=50),
 sec('DPDP ACT 2023', 'g'),
 tb(['Provision', 'Detail'], ['Scope', 'digital personal data in India and extraterritorial for goods/services offered in India'], ['Consent', 'informed and explicit'], ['Children', 'government can lower age of consent'], ['Cross-border', '"blacklisting" approach, not blanket bar'], ['Social media', 'Significant Data Fiduciaries must enable user verification'], ['Exemptions', 'selective, for security and law enforcement'], ['Enforcement', '<b>Data Protection Board of India</b>']),
 bx('pk', '<b>Challenges:</b> <b>vague exemptions for State use:</b> overbroad clauses may dilute privacy and encourage misuse by agencies · <b>weak enforcement:</b> Board\'s effectiveness hinges on autonomy, resources, capacity · <b>compliance burden on innovation:</b> small businesses and start-ups may struggle, stifling digital innovation · <b>international data-sharing frictions:</b> divergence from global data standards could hinder India\'s global digital integration.'),
 sec('CYBERSECURITY', 'r'),
 bx('bl', '<b>Incidents:</b> UIDAI Aadhaar data leak <b>2018</b> (alarm over citizen data privacy) · Kudankulam nuclear plant breach <b>2019</b> (Lazarus Group-led; escalated national-security concerns) · AIIMS Delhi ransomware <b>2022</b> (fragility of healthcare cybersecurity).'),
 bx('pk', '<b>Role of cybersecurity:</b> the backbone of India\'s digital economy; trust in digital governance rests on safeguarding critical infrastructure, preventing intrusions, ensuring data confidentiality: from citizen data in welfare programmes to national security. Threats: ransomware, data breaches, espionage.'),
 t('<b>Initiatives</b>', '<b>CERT-In:</b> nodal agency for cyber-threat response, under MeitY', '<b>National Cyber Security Policy 2013:</b> strategies for securing national digital assets', '<b>Cyber Swachhta Kendra:</b> botnet cleaning, malware mitigation', '<b>ISEA programme:</b> cyber awareness among students and government officials', '<b>Cyber Surakshit Bharat:</b> public-private collaboration for cyber resilience in government institutions', w=36),
 bx('gr', '<b>Way forward:</b> expand operational capacity of CERT-In and I4C; consider a dedicated <b>Cybersecurity Authority for critical sectors</b> · enforce DPDPA 2023 (robust data governance to uphold privacy) · PPP innovation hubs (e.g. Infosys Cyber Defense Center for capacity building) · cyber education in curricula (Cyber Surakshit Bharat) · home-grown R&amp;D (DRDO secure communication systems set precedent).'),
 ],
 recall=[('Right to privacy case', 'Puttaswamy 2017: Fundamental Right'), ('Srikrishna report; first Bill', '2018; PDP Bill 2019'), ('Law now in force', 'DPDP Act, 2023'), ('Hard vs soft localisation', 'never leaves vs conditional sharing'), ('CERT-In falls under', 'MeitY')]),

dict(toc='Emerging tech: blockchain, AI, deepfakes, OTT, DPI', id=24, title='EMERGING TECH IN GOVERNANCE: BLOCKCHAIN · AI · DPI', part=2, icon='pen', prio='M',
 pyq='Mains 2020* (Fourth Industrial Revolution and e-governance) · Handout GEG pp. 20-24',
 simple='New tools (blockchain, AI, DPI) widen what government can do, and bring risks (deepfakes, content regulation, privacy). For each: what, example, challenge, way forward.',
 nodes=[
 sec('BLOCKCHAIN', 'b'),
 bx('bl', '<b>Promise:</b> transparency, immutability, decentralised trust: transforming public service delivery from land records to grievance redressal. <b>CBDC (Digital Rupee):</b> RBI initiative to modernise digital payments and reduce cash dependency. Telangana and Maharashtra pilot blockchain for property registration and digital academic records; regulators TRAI and SEBI exploring it for transparency and efficiency.'),
 tb(['Case', 'Impact'], ['NFTs for land mutation (West Bengal)', 'streamlined land ownership records; eliminated manual processes'], ['Tamil Nadu Blockchain Backbone', 'consolidates citizen documents into a secure digital wallet for easy access and sharing'], ['Firozabad grievance system (UP)', 'transparent complaint redressal using blockchain verification protocols']),
 two([bx('pk', '<b>Challenges:</b> scalability and energy use (high computational demand slows scaling) · legal ambiguity: no robust legal recognition of blockchain records · data privacy: public chains risk exposing sensitive citizen data.')], [bx('gr', '<b>Way:</b> comprehensive regulatory framework akin to <b>Estonia\'s</b> blockchain legal infrastructure · prioritise <b>permissioned</b> blockchains for government use · capacity building and sandbox projects like Dubai\'s Blockchain Strategy.')]),
 sec('AI AND GOVERNANCE (4IR) ' + P('2020*'), 'g'),
 bx('bl', 'AI is reshaping public administration through <b>automation, predictive analytics and efficient service delivery</b>.'),
 t('<b>Uses</b>', '<b>AI-led service delivery:</b> automation reduces administrative burden; e.g. Indian Railways\' "Ideal Train Profile" optimises revenue via AI analysis', '<b>healthcare and education:</b> telemedicine, personalised learning; e.g. NITI Aayog cancer image databases', '<b>agriculture and inclusivity:</b> AI-based pest control; <b>Bhashini</b> project enables language inclusivity', w=38),
 t('<b>National initiatives</b>', '<b>IndiaAI Mission:</b> build indigenous AI infrastructure, including <b>10,000 GPUs</b>', '<b>BharatGen Project:</b> multilingual AI models for India\'s linguistic diversity', '<b>global collaborations:</b> GPAI; bilateral projects like US-India AI partnership', w=30),
 tb(['AI challenge', 'Solution'], ['fragmented data governance', 'implement National Data Governance Policy; open, interoperable datasets'], ['lack of AI-specific legislation', 'draft AI-specific regulations ensuring ethical oversight and transparency'], ['skill deficits in AI workforce', 'expand AI training, especially in rural and underserved regions'], ['privacy and data security concerns', 'enforce DPDPA effectively, focusing on data localisation and protection of sensitive information']),
 sec('DEEPFAKES', 'r'),
 bx('pk', '<b>Deepfakes</b> blur the line between reality and fabrication: a challenge to governance (elections, national security, public trust). <b>Current law:</b> IT Act 2000 Secs <b>66C, 66E, 67, 67A</b> + IPC provisions on defamation, obscenity, forgery. <b>IT Rules 2021:</b> flagged deepfake content to be taken down within <b>36 hours</b>.'),
 bx('bl', '<b>Government response and advisory (2023):</b> directives to intermediaries for timely takedown and user education · engagement with stakeholders for compliance · future IT Rules amendments to enhance platform accountability.'),
 t('<b>Impact on governance</b>', '<b>election misinformation:</b> manipulates voter perception', '<b>national security threats:</b> fabricated military or government communications', '<b>cybercrime and fraud:</b> scams impersonating officials', '<b>erosion of public trust:</b> citizens cannot tell genuine from manipulated content', w=34),
 bx('gr', '<b>Way:</b> <b>platform accountability:</b> detection tools like Microsoft\'s Video Authenticator · <b>blockchain-based verification</b> to trace media authenticity · <b>comprehensive legislation:</b> frame a Digital India Act addressing deepfakes, learning from international frameworks · <b>public awareness:</b> responsible content sharing, media literacy.'),
 sec('OTT AND CONTENT REGULATION', 'b'),
 t('<b>Why and how</b>', '<b>need:</b> explosive growth (<b>424 million</b> users in 2022); obscenity, lack of censorship, minors exposed to inappropriate material; cybersecurity risks: data breaches, fraud', '<b>Digital Media Ethics Code:</b> mandatory content classification: ratings <b>U, UA 7+, 13+, 16+, A</b> and parental controls', '<b>three-tier grievance mechanism:</b> publisher-level redressal, self-regulatory bodies, government oversight', '<b>norm compliance:</b> align digital news with Press Council and Cable TV Programme Codes', '<b>way forward:</b> fast-track DPDPA to safeguard OTT user privacy · common regulator for digital, print and broadcast (Singapore model) · age ratings and content tags in regional languages alongside English · independent audit body for content compliance and data security', w=44),
 sec('DIGITAL PUBLIC INFRASTRUCTURE (DPI)', 'g'),
 bx('bl', '<b>DPI:</b> open-source, interoperable tech platforms underpinning mass delivery of public services, designed to be <b>scalable, inclusive and secure</b>. <b>India Stack:</b> Aadhaar, UPI, DigiLocker. Also <b>ONDC, Open Health Stack, NDEAR</b> (education; DIKSHA).'),
 tb(['Platform', 'Purpose'], ['Aadhaar', 'digital identity, presenceless authentication'], ['UPI', 'real-time interoperable payments'], ['DigiLocker', 'paperless documents'], ['ONDC', 'open digital commerce'], ['Open Health Stack', 'secure health-data sharing'], ['NDEAR', 'national digital education architecture (DIKSHA)']),
 t('<b>Significance</b>', '<b>digital inclusion and financial access:</b> ~<b>80%</b> financial inclusion in 6 years vs expected 46-year trajectory; UPI brought digital payments to rural India, widening formal credit and savings access', '<b>economic gain:</b> DPI could add <b>2.9-4.2%</b> of GDP by 2030, pivotal to the $8 trillion economy ambition', '<b>govt efficiency and innovation:</b> CSCs extend Digital India to remote areas through local entrepreneurs', '<b>AP ICJS 2.0 (Interoperable Criminal Justice System):</b> police, forensics, courts, prisons digitised with AI-powered coordination: transparency and efficiency', w=44),
 t('<b>Challenges</b>', '<b>digital divide:</b> disparity across regions, castes, socio-economic groups; <b>70%</b> of rural population lacks reliable connectivity; limited devices and training', '<b>privacy and trust deficit:</b> broad digital identity raises surveillance and misuse concerns; unclear redress mechanisms and absent robust legal framework erode trust', '<b>state capacity and institutional gaps:</b> need strong frameworks and <b>"intelligent customers"</b> (state actors knowledgeable in risk and data governance)', '<b>implementation disparity across states:</b> Madhya Pradesh only <b>0.9%</b> schools with digital libraries vs national <b>6.1%</b>', w=44),
 t('<b>Way forward</b>', '<b>bridge connectivity and literacy gap:</b> National Broadband Mission 2.0 (universal rural broadband); digital literacy via CSCs and PMGDISHA-like schemes', '<b>institutionalise data trust:</b> embed privacy, contestability, grievance redress from inception; procedural fairness, not just compliance', '<b>state capacity and hybrid institutions:</b> become intelligent DPI customers; State-civil society collaboration', '<b>scale through PPP and innovation:</b> open-source interoperable platforms; e.g. Google\'s investment in Indian data centres', '<b>DPI for new sectors:</b> power (India Stack-like for utilities), education (DIKSHA-based NDEAR), health (Open Health Stack)', w=44),
 ],
 recall=[('IT Rules 2021 takedown time', '36 hours'), ('IndiaAI Mission GPUs', '10,000'), ('Media rating labels', 'U, UA 7+, 13+, 16+, A'), ('India Stack', 'Aadhaar, UPI, DigiLocker'), ('DPI GDP estimate', '2.9-4.2% by 2030')]),
